import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed values
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "returns");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (!dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // Build query - sortCol is user-controlled and injected directly
        String baseQuery = "SELECT id, product_name, quantity, price, created_at " +
                "FROM report_" + reportType + " " +
                "WHERE created_at BETWEEN '" + startDate + "' AND '" + endDate + "'";

        // Sort column injection point - no validation on sortCol
        if (sortCol != null && !sortCol.isEmpty()) {
            baseQuery += " ORDER BY " + sortCol;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(baseQuery)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("{\"id\":%d,\"product\":\"%s\",\"qty\":%d,\"price\":%.2f}",
                    rs.getInt("id"),
                    rs.getString("product_name").replace("\"", "\\\""),
                    rs.getInt("quantity"),
                    rs.getDouble("price"));
            }
            out.print("\n]");
        } catch (SQLException e) {
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch export endpoint - reads body as CSV of IDs
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        String ids = body.toString().trim();
        // Basic format check but doesn't prevent injection in edge cases
        if (!ids.matches("[0-9,\\s]+")) {
            resp.sendError(400, "Invalid ID list");
            return;
        }

        String query = "SELECT * FROM report_sales WHERE id IN (" + ids + ")";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {
            resp.setContentType("text/csv");
            PrintWriter out = resp.getWriter();
            out.println("id,product,quantity,price");
            while (rs.next()) {
                out.printf("%d,%s,%d,%.2f%n",
                    rs.getInt("id"),
                    rs.getString("product_name"),
                    rs.getInt("quantity"),
                    rs.getDouble("price"));
            }
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }
}
